async function bundledContent(name){const file=contentLocations[name];if(!file)throw Error('Content is not included in this version.');if(!contentBundles.has(file)){const promise=fetch(file).then(async r=>{if(!r.ok)throw Error('A library file is missing. Upload all library files from the ZIP.');return r.json()}).catch(e=>{contentBundles.delete(file);throw e});contentBundles.set(file,promise)}const raw=(await contentBundles.get(file))[name];while(contentBundles.size>2){const key=contentBundles.keys().next().value;if(key===file){const value=contentBundles.get(key);contentBundles.delete(key);contentBundles.set(key,value)}else contentBundles.delete(key)}if(typeof raw!=='string')throw Error('Content is missing from the library.');return new TextEncoder().encode(raw).buffer}
