function bindV5(){
 by('templateV5')?.addEventListener('click',()=>download('OneHome-Arbor-template.csv',csv([['Student Name','Classes','Parent Email','Year']])+'\r\n','text/csv'));
 const invalidate=()=>{rosterPreview=null;if(by('rosterSave'))by('rosterSave').disabled=true;if(by('rosterSummary'))by('rosterSummary').textContent='Preview again after changes.'};
 by('rosterFile')?.addEventListener('change',e=>run(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('Choose a CSV under 2 MB.');by('rosterText').value=await f.text();importMap=null;by('columnMap').innerHTML='';by('rosterPreview').disabled=true;invalidate()}));
 by('rosterText')?.addEventListener('input',()=>{importMap=null;by('columnMap').innerHTML='';by('rosterPreview').disabled=true;invalidate()});
 for(const id of ['rosterYear','rosterSource','rosterProvider','rosterMembership'])by(id)?.addEventListener('change',invalidate);
 by('mapColumns')?.addEventListener('click',()=>run(async()=>{const {columns,fields}=await import('./roster.mjs');const {headers,map}=columns(by('rosterText').value);importMap=map;by('columnMap').innerHTML=Object.keys(fields).map(k=>'<label>'+({name:'Full name',first:'First name',last:'Last name',parentEmail:'Parent email',email:'School email (optional)',year:'Year',classes:'Classes',externalId:'Student ID (optional)'}[k])+'<select data-column="'+k+'">'+options([[-1,'Not included'],...headers.map((h,i)=>[i,h])],map[k])+'</select></label>').join('');by('rosterPreview').disabled=false;by('columnMap').querySelectorAll('select').forEach(s=>s.onchange=()=>{importMap[s.dataset.column]=Number(s.value);invalidate()});invalidate()}));
 by('rosterPreview')?.addEventListener('click',()=>run(async()=>{invalidate();const {roster}=await import('./roster.mjs');rosterPreview=roster(by('rosterText').value,importMap,by('rosterYear').value,by('rosterProvider').value);const matches=rosterPreview.rows.filter(r=>state.students.some(s=>s.email?.toLowerCase()===r.email)).length;by('rosterSummary').innerHTML='<h3>'+rosterPreview.rows.length+' students · '+rosterPreview.classes.length+' shared classes</h3><p>'+rosterPreview.duplicates+' repeated rows combined · '+matches+' existing email matches. '+(by('rosterMembership').value==='replace'?'This replaces each imported student’s current class memberships.':'Existing classes will be kept, up to 10 per student.')+'</p>'+table(['Student','Parent email','Year','Classes'],rosterPreview.rows.map(r=>[esc(r.first+' '+r.last),esc(r.parentEmail),r.year,esc(r.classes.join(', '))]));by('rosterSave').disabled=false}));
 by('rosterForm')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{if(!rosterPreview)throw Error('Preview your import first.');const result=await call('roster_v7',{rows:rosterPreview.rows,source:by('rosterSource').value,membership:by('rosterMembership').value});download('OneHome-private-login-codes.csv',csv([['Name','ID','New login code'],...result.map(r=>[r.name,r.id,r.code||'Existing code unchanged'])]),'text/csv');rosterPreview=null;await refresh();toast('Students and shared classes imported. Keep the downloaded codes private.')},e.submitter)});
 by('managedClass')?.addEventListener('change',e=>{classFilter=e.target.value;render()});
 by('memberForm')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const students=new FormData(e.target).getAll('pupil');if(!students.length)throw Error('Select students first.');await call('membership',{students,class:classFilter,operation:by('memberOperation').value,to:by('memberTo').value});await refresh();toast('Class memberships updated.')},e.submitter)});
 by('graduatesOpen')?.addEventListener('click',()=>run(async()=>{graduates=await call('graduates');view='graduates';render()}));
 by('graduateForm')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target);await call('graduate',{students:f.getAll('graduate'),confirm:f.get('confirm')});graduates=await call('graduates');await refresh();toast('Selected Year 11 students graduated. Their records are preserved.')},e.submitter)});
 document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>run(async()=>{await call('restore_graduate',{student:b.dataset.restore});graduates=await call('graduates');await refresh();toast('Student access restored.')},b));
 by('comfortForm')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);comfort={font:f.get('font'),width:f.get('width'),letters:f.get('letters'),motion:f.has('motion'),reminder:Number(f.get('reminder'))};localStorage.setItem('onehome-comfort',JSON.stringify(comfort));activeMinutes=0;render();toast('Comfort settings saved.')});
 document.querySelectorAll('[data-buddy]').forEach(b=>b.onclick=()=>run(async()=>{wallet=await call('buddy_type',{buddy:b.dataset.buddy});render();toast('Your new study buddy is ready.')},b));
 document.querySelectorAll('[data-door]').forEach(b=>b.onclick=()=>run(async()=>{advent=await call('advent_claim',{day:Number(b.dataset.door)});wallet=await call('wallet');render();toast('Your December gift is saved.')},b));
 document.querySelectorAll('[data-pass-year].pass-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();run(async()=>{advent=await call('pass_request',{year:Number(f.dataset.passYear),task:new FormData(f).get('task')});render();toast('Request sent to your homework teacher.')},e.submitter)});
 document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>run(async()=>{await call('pass_decide',{student:b.dataset.passStudent,year:Number(b.dataset.passYear),status:b.dataset.decision});await refresh();toast('Homework pass request updated.')},b));
}



