async function call(action,data={}){
 if(action==='answer'&&opened?.review)data.review=true;
 const res=await baseCall(action,data);
 if(action==='staff'||action==='student'){
  workspace=await baseCall(action==='student'?'workspace_student':'workspace_staff');
  if(action==='student')for(const t of res.tasks){const o=workspace.overrides.find(o=>o.task_id===t.id);if(o){t.due_at=o.due_at||t.due_at;t.exempt=o.exempt;t.feedback=o.feedback}}
 }
 return res;
}
function v7Page(){return ({today:todayPage,week:weekPage,revise:revisionPage,notebook:notebookPage,messages:messagesPage,schoolcontent:schoolContentPage,learning:learningPage,teacherhub:teacherHub,exam:examPage,literature:literaturePage,activities:activitiesPage,options:optionsPage,progress:progressPage})[view]?.()??null}
function home(){return student()?todayPage():baseHome()+teacherSummary()}
function weekPage(){return heading('My week','Homework, deadlines and personal goals.')+'<section class="card">'+studentTasks()+'</section>'+goalsCard()}
function todayPage(){
 const recent=state.progress.filter(p=>p.id!=='wallet'&&p.data&&!p.data.complete&&state.catalog.some(c=>p.id===c.id||p.id.startsWith(c.id+':'))).sort((a,b)=>new Date(b.updated_at||0)-new Date(a.updated_at||0)).slice(0,3);
 const tasks=state.tasks.filter(t=>!t.exempt).sort((a,b)=>new Date(a.due_at)-new Date(b.due_at)).slice(0,3);
 return heading('Today, '+esc(state.student.first),'One step at a time. Choose what you need next.')+`<div class="grid three"><section class="card"><span class="eyebrow">Continue learning</span><h2>Pick up where you left off</h2>${recent.map(p=>{const c=state.catalog.find(c=>p.id===c.id||p.id.startsWith(c.id+':'));const task=p.id.startsWith(c.id+':')?p.id.slice(c.id.length+1):'';return '<button class="secondary space" data-resume="'+esc(c.id)+'" data-resume-task="'+esc(['revision','recap'].includes(task)?'':task)+'">'+esc(c.title)+'</button>'}).join('')||'<p>Unfinished books and practice appear here.</p>'}</section><section class="card"><span class="eyebrow">Coming up</span><h2>Homework</h2>${tasks.map(t=>'<p><b>'+esc(t.title)+'</b><br><small>'+fmt(t.due_at)+'</small></p>').join('')||'<p>No homework due.</p>'}<button data-view="week">My week</button></section><section class="card"><span class="eyebrow">A little every day</span><h2>Review & remember</h2><p>Revisit tricky skills and keep learning fresh.</p><button data-view="revise">My revision</button><button class="secondary space" data-view="literature">GCSE literature</button></section></div><div class="space">${serviceCards()}</div>${goalsCard()}<div class="grid space">${petCard()}${walletCard()}</div>`;
}
function goalsCard(){const n=workspace.notes?.goals||{},target=Number(n.minutes)||60;return `<form id="goalForm" class="card space"><h2>My weekly goal</h2><p>Missing a day never resets your achievements.</p><label>Study minutes this week<input name="minutes" type="number" min="10" max="600" step="10" value="${target}"></label><label>My focus<input name="focus" maxlength="160" value="${esc(n.focus||'')}" placeholder="Read three times and practise fractions"></label><p>Goal started: ${esc(n.week||'Set your first goal below')} · ${Math.max(0,studyMinutes(state.student.id)-(n.baseline||0))} / ${target} minutes since setting this goal</p><button>Save goal</button></form>`}
function optionsPage(){return heading('Content options','School resources have their own collection.')+'<div class="grid"><section class="card"><h2>OneHome library</h2><p>Our books and grouped maths skills.</p><button data-view="library">Browse built-in content</button></section><section class="card"><h2>Our school content</h2><p>Books and topics supplied by your school.</p><button data-view="schoolcontent">Open school collection</button></section></div>'}
function schoolContentPage(){const own=state.catalog.filter(c=>c.schoolOwned||c.id.startsWith('custom-'));return heading('Our school content','Separate from the built-in OneHome library.')+(admin()?'<div class="toolbar"><button data-view="upload">Add school book</button><button id="showMathEditor" class="secondary">Create maths topic</button></div><section id="mathEditor" class="card space" hidden><h2>Create a school maths topic</h2><form id="schoolMathForm"><label>Title<input name="title" required maxlength="120"></label><label>Year<select name="year">'+options([7,8,9,10,11].map(y=>[y,y]),10)+'</select></label><label>Topic area<input name="strand" value="School topics" maxlength="80"></label><p>One question per line: Question | Choice 1 | Choice 2 | Choice 3 | Choice 4 | Correct choice number (1–4) | Hint</p><textarea name="questions" rows="10" required placeholder="What is 2 + 3? | 4 | 5 | 6 | 7 | 2 | Count on three."></textarea><button>Save school topic</button></form></section>':'')+'<div class="book-grid space">'+own.map(c=>'<article class="card book"><span class="badge">School '+(c.kind==='math'?'maths':'book')+'</span><h3>'+esc(c.title)+'</h3><button data-'+(student()?'open':'preview')+'="'+esc(c.id)+'">'+(student()?'Open':'Preview')+'</button></article>').join('')+'</div>'+(own.length?'':'<p class="card space">Your school has not added resources yet.</p>')}
function peopleV7(){const persons=personKind==='student'?state.students:(state.members||[]).filter(p=>!p.role||p.role==='teacher');if(!persons.some(p=>p.id===personId)){personId=persons[0]?.id||'';if(personKind==='student'&&persons[0])personYear=String(persons[0].year);}const p=persons.find(p=>p.id===personId),classes=state.classes.filter(c=>String(c.year)===personYear);
 return heading('People & classes','Person → year → allowed classes','<button id="exportRosterV7" class="secondary">Export roster with IDs</button>')+`<section class="card"><div class="form-grid"><label>Manage<select id="personKind">${options([['student','Students'],['teacher','Teachers']],personKind)}</select></label><label>Person<select id="personId">${options(persons.map(p=>[p.id,p.first?name(p):p.email||p.name||p.id]),personId)}</select></label><label>Year<select id="personYear">${options([7,8,9,10,11].map(y=>[y,'Year '+y]),personYear)}</select></label></div><form id="peopleAssign"><p>${personKind==='student'?'Choose 1–10 classes. Saving replaces this student’s year and classes.':'Up to 10 classes in this year. Other years are kept. None removes access to this year.'}</p><div class="selection-list">${classes.map(c=>'<label><input name="classes" type="checkbox" value="'+esc(c.id)+'" '+((personKind==='student'?p?.class_ids||[]:c.staff_ids||[]).includes(personKind==='student'?c.id:personId)?'checked':'')+'>'+esc(c.name)+'</label>').join('')||'<p>Import classes for this year first.</p>'}</div><p id="classCounter"></p><button ${!p?'disabled':''}>Save assignments</button></form></section>`+ '<details class="space"><summary>Class tools, full roster and sign-in emails</summary>'+basePeopleV5().replace(/<header class="page-title">[\s\S]*?<\/header>/,'')+'</details>';
}
function pointGuide(){return `<section class="card space"><h2>Reading time → Star Points</h2><p>A planning estimate, not a timer or reading-speed judgement. Start with 10 points per 10 minutes and adjust for your class. Double-point mode doubles suggestions.</p><div class="toolbar">${[10,20,30,40,50,60].map(m=>'<button type="button" class="secondary" data-time-points="'+m+'">'+m+' min · '+(m*(state.settings.starReader?2:1))+' ★</button>').join('')}</div><small>Choose enough checkpoints for an achievable target. Points come from comprehension checkpoints.</small></section>`}
function teacherSummary(){return '<section class="card space"><h2>Your teaching tools</h2><p>Progress, help requests, deadlines and reusable homework.</p><div class="toolbar"><button data-view="teacherhub">Teacher dashboard</button><button class="secondary" data-view="messages">Student messages</button></div></section>'}
function teacherHub(){const counts={};for(const a of workspace.attempts.filter(a=>a.correct_first===false))counts[a.item]=(counts[a.item]||0)+1;
 return heading('Teacher dashboard','Your classes and their next steps.')+`<div class="grid three"><section class="card"><h2>${state.classes.length}</h2><p>Allowed classes</p></section><section class="card"><h2>${state.tasks.filter(t=>new Date(t.due_at)<new Date()).length}</h2><p>Past-deadline assignments to review</p></section><section class="card"><h2>${workspace.messages.filter(m=>m.sender==='student').length}</h2><p>Student messages in your inbox</p><button data-view="messages">Open messages</button></section></div><section class="card space"><h2>Common mistakes</h2>${table(['Topic','Questions needing another attempt'],Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,20).map(([id,n])=>[esc(state.catalog.find(c=>c.id===id)?.title||id),n]))}<p>Counts show first answers that needed correction, not a diagnosis of ability.</p></section><section class="card space"><h2>Individual support</h2><form id="taskAdjust"><div class="form-grid"><label>Homework<select name="task" id="adjustTask">${options(state.tasks.map(t=>[t.id,t.title]),'')}</select></label><label>Student<select name="student" id="adjustStudent"></select></label><label>New deadline (optional)<input type="datetime-local" name="due"></label></div><label><input type="checkbox" name="exempt">Excuse this student from this homework</label><label>Private feedback<textarea name="feedback" maxlength="2000"></textarea></label><button ${!state.tasks.length?'disabled':''}>Save support</button></form></section><section class="card space"><h2>Saved assignment templates</h2>${workspace.templates.map(t=>'<div class="row"><span>'+esc(t.title)+(t.shared?' · School shared':' · Private')+'</span><button data-template="'+esc(t.id)+'">Use template</button></div>').join('')||'<p>Save a template from the homework planner.</p>'}</section><section class="card space"><h2>Student skill progress</h2>${table(['Student','Practised questions','First answers correct','Needs review'],state.students.map(s=>{const a=workspace.attempts.filter(a=>a.student_id===s.id);return [esc(name(s)),a.length,a.filter(v=>v.correct_first).length,a.filter(v=>!v.solved).length]}))}</section>`;
}
function messagesPage(){const paused=workspace.sunday||isSunday();return heading('Teacher messages','Ask for help or follow up on feedback.')+`${paused?'<div class="notice">Sunday pause · Read messages today; sending resumes Monday, UK time.</div>':'<p class="hint">Messages stay inside OneHome. Teachers may reply during working hours.</p>'}<div class="grid space"><form id="messageForm" class="card"><h2>New message</h2><label>${student()?'Teacher':'Student'}<select name="recipient" required>${options((student()?workspace.contacts:state.students).map(p=>[p.id,p.first?name(p):p.email||p.name||p.id]),'')}</select></label><label>Question or homework<input name="context" maxlength="250" value="${esc(messageContext)}"></label><label>Message<textarea name="body" rows="6" maxlength="2000" required></textarea></label><button ${paused?'disabled':''}>Send message</button></form><section class="card"><h2>Conversation history</h2><div class="message-history">${workspace.messages.slice(-100).reverse().map(m=>'<article class="message '+esc(m.sender)+'"><b>'+esc(m.sender==='student'?(student()?'You':name(state.students.find(s=>s.id===m.student_id)||{first:'Student',last:''})):(student()?'Your teacher':'You'))+'</b><small>'+fmt(m.sent_at)+'</small>'+(m.context?'<p class="hint">'+esc(m.context)+'</p>':'')+'<p>'+esc(m.body)+'</p></article>').join('')||'<p>No messages yet.</p>'}</div></section></div>`}
function revisionPage(){const groups=new Map();for(const c of state.catalog.filter(c=>c.kind==='math'&&Number(c.year)<=state.student.year)){const key=c.skill||c.title.replace(/ · Set \d+$/,'');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(c)}
 const rows=[...groups].map(([skill,items])=>{const a=workspace.attempts.filter(a=>items.some(c=>c.id===a.item));const last=Math.max(0,...a.map(a=>new Date(a.last_at).getTime())),wrong=a.filter(a=>!a.solved).length,first=a.length?a.filter(a=>a.correct_first).length/a.length:0;return {skill,items,a,wrong,last,due:last+(first>.8?7:first>.5?3:1)*86400000,status:!a.length?'Not started':wrong?'Practising':first>.8&&a.length>=8?'Secure':'Practising'}}).sort((a,b)=>b.wrong-a.wrong||(a.a.length?0:1)-(b.a.length?0:1)||a.due-b.due);
 return heading('My revision','Suggestions based on your answers. Ask your teacher about the right level.')+`<div class="toolbar"><button data-view="exam">Exam practice</button><button class="secondary" data-view="activities">Interactive practice</button></div><div class="book-grid space">${rows.slice(0,24).map(r=>'<article class="card"><span class="badge">'+r.status+'</span><h3>'+esc(r.skill)+'</h3><p>'+(!r.a.length?'Try this skill':r.due<Date.now()?'Ready for a recap':'Suggested recap: '+new Date(r.due).toLocaleDateString('en-GB'))+'</p><button data-learn="'+esc((r.items.find(c=>!r.a.some(a=>a.item===c.id))||r.items[0]).id)+'">Learn & practise</button></article>').join('')}</div><section class="card space"><h2>My mistake notebook</h2>${table(['Skill','Question','Status',''],workspace.attempts.filter(a=>a.correct_first===false).slice(-40).map(a=>[esc(state.catalog.find(c=>c.id===a.item)?.title||a.item),a.question+1,a.solved?'Corrected':'Try again','<button class="secondary" data-learn="'+esc(a.item)+'">Review method</button>']))}</section>`;
}
function baseLearningPage(){if(!lessonItem)return '<p>Choose a skill.</p>';const d=lessonItem.content;return heading(esc(d.skill||d.title),'Learn → practise → review')+`<section class="card lesson"><span class="badge">Learn the method</span><h2>${esc(d.skill||d.title)}</h2><p>${esc(d.lesson?.method||d.questions[0]?.hint||'Read carefully and work through one step at a time.')}</p>${d.lesson?.example?'<div class="notice"><h3>Worked example</h3><p>'+esc(d.lesson.example.prompt)+'</p><p>'+esc(d.lesson.example.solution)+'</p></div>':''}<button id="startLesson" class="space">Practise this skill</button><button id="askLesson" class="secondary space">Ask my teacher</button></section>`}
function notebookPage(){const saved=Object.entries(workspace.notes||{}).filter(([id])=>id!=='goals');return heading('My reading notebook','Private bookmarks and notes, saved to your account.')+'<div class="stack">'+saved.map(([id,n])=>'<article class="card"><h2>'+esc(state.catalog.find(c=>c.id===id)?.title||n.title||id)+'</h2><p>'+esc(n.note||'')+'</p><p>'+esc(n.vocabulary||'')+'</p><p>'+esc(n.inference||'')+'</p><p>'+esc(n.evidence||'')+'</p><small>Bookmark: page '+((Number(n.page)||0)+1)+'</small>'+(state.catalog.some(c=>c.id===id)?'<button class="secondary" data-open="'+esc(id)+'">Continue reading</button>':'')+'</article>').join('')+'</div>'+(saved.length?'':'<section class="card">Open a book to save a note.</section>')}
function noteControls(){const n=workspace.notes?.[opened.id]||{};return `<section class="card space"><h2>My bookmark & note</h2><form id="readingNote"><label>Private note<textarea name="note" maxlength="4000">${esc(n.note||'')}</textarea></label><button>Save note & bookmark this page</button></form><button class="quiet space" id="askReading">Ask my teacher about this page</button></section>`}
function buddyExtras(){return `<section class="card space"><h2>A little lift from ${esc(buddyName())}</h2><div class="toolbar"><button id="randomBuddyName" class="secondary">Surprise me with a name</button><span>${studentExtras.names.length} ready-made names</span></div><label>Joke topic<input id="jokeTopic" placeholder="Maths, books, animals, space…"></label><button id="buddyJoke" class="space">Tell me a joke</button><p id="jokeAnswer" class="joke" aria-live="polite"></p><small>Jokes from our topic collection. Unknown topics get a general joke.</small></section>`}
function examPage(){return heading('Exam practice','Original GCSE-style practice, not official papers or predicted grades.')+`<section class="card"><label>Topic<select id="examTopic">${options(state.catalog.filter(c=>c.kind==='math'&&c.year>=10).map(c=>[c.id,c.title]),'')}</select></label><label><input type="checkbox" id="examTimed">Show an optional 15-minute timer</label><button id="examStart">Start practice</button><p>School exam board: ${esc(state.settings.board||'not set')}.</p></section>`}
function literaturePage(){const texts=[['Macbeth','Ambition, power, guilt and the supernatural','Trace how Macbeth changes after hearing the predictions.','Explain how Shakespeare presents the consequences of ambition.'],['A Christmas Carol','Responsibility, generosity, poverty and change','Compare Scrooge’s attitudes at the beginning and end.','Explain how Dickens presents social responsibility.'],['An Inspector Calls','Responsibility, class, gender and generations','Compare how the older and younger characters respond to the Inspector.','Explain how Priestley presents different attitudes to responsibility.']];return heading('GCSE literature workspace','Original prompts for your school’s chosen texts.')+texts.map(([title,themes,characters,prompt])=>`<section class="card space"><h2>${title}</h2><h3>Themes</h3><p>${themes}</p><h3>Character connections</h3><p>${characters}</p><h3>Paragraph practice</h3><p>${prompt}</p><form data-lit="${esc(title)}"><label>Your paragraph<textarea name="note" maxlength="4000" rows="5">${esc(workspace.notes?.['lit-'+title]?.note||'')}</textarea></label><details><summary>Self-check your paragraph</summary><p>Make a clear point. Use a short accurate quotation from your edition. Explain a word, image or dramatic choice. Link it to the question and relevant context. Consider an alternative interpretation.</p></details><button class="space">Save private draft</button></form></section>`).join('')}
function activitiesPage(){return heading('Interactive practice','Warm-ups in different formats. No points are awarded.')+`<div class="grid"><form class="card" id="orderActivity"><h2>Order these fractions</h2><p>Put 1/2, 3/4 and 1/4 in ascending order.</p>${['Smallest','Middle','Largest'].map((label,i)=>'<label>'+label+'<select name="'+i+'">'+options(['1/2','3/4','1/4'].map(v=>[v,v]),'1/2')+'</select></label>').join('')}<button>Check order</button></form><form class="card" id="matchActivity"><h2>Match fractions and decimals</h2>${[['1/2','half'],['1/4','quarter'],['3/4','three']].map(([l,n])=>'<label>'+l+'<select name="'+n+'">'+options(['0.25','0.5','0.75'].map(v=>[v,v]),'0.25')+'</select></label>').join('')}<button>Check matches</button></form><form class="card" id="graphActivity"><h2>Plot a point</h2><p>Place a point on y = 2x + 1, using x = 2.</p><svg viewBox="0 0 240 180" class="practice-graph"><path d="M30 10V150H230" fill="none" stroke="currentColor"/><text x="220" y="170">x</text><text x="10" y="20">y</text><g font-size="10" fill="currentColor"><text x="25" y="165">0</text><text x="67" y="165">1</text><text x="107" y="165">2</text><text x="147" y="165">3</text><text x="187" y="165">4</text><text x="15" y="123">2</text><text x="15" y="93">4</text><text x="15" y="63">6</text><text x="15" y="33">8</text></g><path d="M30 120H220M30 90H220M30 60H220M30 30H220M70 10V150M110 10V150M150 10V150M190 10V150" stroke="#ddd"/><circle id="graphPoint" cx="110" cy="150" r="6" fill="#653baf"/></svg><label>y-coordinate<input name="y" type="number" min="0" max="9" value="0"></label><button>Check point</button></form><section class="card"><h2>Explain your reasoning</h2><p>Why is the sum of two odd integers always even?</p><textarea aria-label="Your explanation" rows="4"></textarea><details><summary>Compare with a model explanation</summary><p>Write the numbers as 2a+1 and 2b+1. Their sum is 2(a+b+1), a multiple of 2, so it is even.</p></details></section></div><p id="activityResult" class="notice" aria-live="polite">Choose a warm-up.</p>`}
function numberValue(s){s=String(s).trim().replace(/−/g,'-').replace(/,/g,'');if(/^[+-]?\d+\/[+-]?\d+$/.test(s)){const [a,b]=s.split('/').map(Number);return b?a/b:NaN}return /^[+-]?(?:\d+\.?\d*|\.\d+)$/.test(s)?Number(s):NaN}
