 for(const [id,key] of [['personKind','kind'],['personId','person'],['personYear','year']])by(id)?.addEventListener('change',e=>{if(key==='kind'){personKind=e.target.value;personId=''}if(key==='person'){personId=e.target.value;const p=state.students.find(p=>p.id===personId);if(personKind==='student'&&p)personYear=String(p.year)}if(key==='year')personYear=e.target.value;render()});
 const countClasses=()=>{if(by('classCounter'))by('classCounter').textContent=document.querySelectorAll('#peopleAssign input:checked').length+' of 10 selected'};countClasses();by('peopleAssign')?.addEventListener('change',e=>{if(document.querySelectorAll('#peopleAssign input:checked').length>10){e.target.checked=false;toast('Select up to 10 classes.')}countClasses()});
