 document.querySelectorAll('[data-resume]').forEach(b=>b.onclick=()=>run(async()=>{service=state.catalog.find(c=>c.id===b.dataset.resume)?.kind==='math'?'maths':'reader';await openItem(b.dataset.resume,b.dataset.resumeTask||null)},b));
