 by('readingNote')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const data={...(workspace.notes[opened.id]||{}),note:new FormData(e.target).get('note'),page,title:opened.content.title};await call('notebook_save',{item:opened.id,data});workspace.notes[opened.id]=data;toast('Private note and bookmark saved.')},e.submitter)});
