 document.querySelectorAll('[data-time-points]').forEach(b=>b.onclick=()=>{const input=document.querySelector('#taskForm [name=points]');if(input)input.value=Number(b.dataset.timePoints)*(state.settings.starReader?2:1)});
 const fillStudents=()=>{const t=state.tasks.find(t=>t.id===by('adjustTask')?.value);if(by('adjustStudent'))by('adjustStudent').innerHTML=options(state.students.filter(s=>s.class_ids.includes(t?.class_id)).map(s=>[s.id,name(s)]),'')};fillStudents();by('adjustTask')?.addEventListener('change',fillStudents);
 by('taskAdjust')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target);await call('task_adjust',{task:f.get('task'),student:f.get('student'),due:f.get('due')?new Date(f.get('due')).toISOString():null,exempt:f.has('exempt'),feedback:f.get('feedback')});await refresh();toast('Student support saved.')},e.submitter)});
