 for(const [id,check] of [['orderActivity',f=>f.get('0')==='1/4'&&f.get('1')==='1/2'&&f.get('2')==='3/4'],['matchActivity',f=>f.get('half')==='0.5'&&f.get('quarter')==='0.25'&&f.get('three')==='0.75'],['graphActivity',f=>Number(f.get('y'))===5]])by(id)?.addEventListener('submit',e=>{e.preventDefault();by('activityResult').textContent=check(new FormData(e.target))?'Correct — well done.':'Not yet. Check equivalent values or substitute x into the equation, then try again.'});
