function library(){if(service==='reader')return baseLibrary();const all=catalog('math').filter(c=>!c.schoolOwned&&!c.id.startsWith('custom-')&&(!search||(c.skill||c.title).toLowerCase().includes(search.toLowerCase()))&&(!filter||String(c.year)===filter)&&(!strandFilter||c.strand===strandFilter)),groups=new Map();for(const c of all){const key=c.skill||c.title.replace(/ · Set \d+$/,'');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(c)}const rows=[...groups].sort((a,b)=>a[0].localeCompare(b[0])),pages=Math.max(1,Math.ceil(rows.length/24));libraryPage=Math.max(0,Math.min(libraryPage,pages-1));return heading('Choose a maths skill','Practice sets are grouped under each skill. School topics have their own collection.')+'<div class="toolbar"><label>Search<input id="search" value="'+esc(search)+'" placeholder="Find a skill"></label><label>Year<select id="filter">'+options([['','All'],...[7,8,9,10,11].map(y=>[y,y])],filter)+'</select></label><label>Topic area<select id="strandFilter">'+options([['','All areas'],...['Number','Algebra','Ratio and proportion','Geometry and measures','Probability and statistics'].map(s=>[s,s])],strandFilter)+'</select></label><button id="applyFilter">Apply filters</button><button class="secondary" data-view="schoolcontent">School topics</button></div><p class="space">'+rows.length+' skills · '+all.length+' sets · Page '+(libraryPage+1)+' of '+pages+'</p><div class="book-grid space">'+rows.slice(libraryPage*24,(libraryPage+1)*24).map(([skill,sets])=>'<article class="card skill"><span class="badge">Year '+sets[0].year+' · '+esc(sets[0].strand||'Maths')+'</span><h3>'+esc(skill)+'</h3><p>'+sets.length+' practice sets</p><details><summary>Choose a set</summary>'+sets.map(c=>'<div class="row"><span>'+esc(c.title)+'</span><button class="secondary" data-'+(student()?'learn':'preview')+'="'+esc(c.id)+'">'+(student()?'Learn':'Preview')+'</button></div>').join('')+'</details></article>').join('')+'</div><div class="toolbar space"><button id="libraryPrev" class="secondary" '+(libraryPage===0?'disabled':'')+'>Previous page</button><button id="libraryNext" class="secondary" '+(libraryPage===pages-1?'disabled':'')+'>Next page</button></div>'}



function studentNav(menu){
 const primary=[['home','home','Today'],['library',service==='maths'?'maths':'reader','Learn'],['week','planner','Homework'],['revise','maths','Revise'],['progress','reports','My progress'],['messages','people','Messages']];
 const button=([id,i,label])=>'<button data-view="'+id+'" class="'+(view===id?'active':'')+'">'+icon(i)+label+'</button>';
 return primary.map(button).join('')+'<details class="nav-extra"><summary>My books, buddy & settings</summary>'+menu.filter(m=>!primary.some(p=>p[0]===m[0])&&!['homework'].includes(m[0])).map(button).join('')+'</details>';
}
function progressPage(){const attempts=workspace.attempts,correct=attempts.filter(a=>a.correct_first).length,finished=state.progress.filter(p=>p.data?.complete&&p.id!=='reading-check').length;return heading('My progress','Your own learning journey. No public rankings.')+'<div class="grid three"><section class="card"><h2>'+finished+'</h2><p>Completed books and practice sessions</p></section><section class="card"><h2>'+attempts.length+'</h2><p>Questions practised since this update</p></section><section class="card"><h2>'+(attempts.length?Math.round(correct/attempts.length*100):0)+'%</h2><p>First answers correct since this update</p></section></div>'+goalsCard()+'<section class="card space"><h2>Personal milestones</h2>'+[1,10,25,50,100].map(n=>'<span class="badge space">'+(attempts.length>=n?'✓ ':'○ ')+n+' questions practised</span>').join('')+'</section>'}



function learningPage(){let html=baseLearningPage();if(!lessonItem||!student())return html;const c=state.catalog.find(c=>c.id===lessonItem.id),attempts=workspace.attempts.filter(a=>a.item===lessonItem.id);if(attempts.filter(a=>!a.solved).length>=2){const easier=state.catalog.find(x=>x.kind==='math'&&x.strand===c?.strand&&Number(x.year)<Number(c?.year));if(easier)html+='<section class="notice space"><h2>Build confidence first</h2><p>A related earlier skill may help. Your teacher can confirm the right next step.</p><button data-learn="'+esc(easier.id)+'">'+esc(easier.skill||easier.title)+'</button></section>'}return html}
function comprehensionTools(){const n=workspace.notes?.[opened.id]||{};return '<section class="card space"><h2>Think about this passage</h2><p>Go beyond remembering facts. These reflections are private and are not automatically marked.</p><form id="readingReflection"><label>Vocabulary: choose a word and explain its meaning here<textarea name="vocabulary" maxlength="1000">'+esc(n.vocabulary||'')+'</textarea></label><label>Inference: what does the passage suggest without saying directly?<textarea name="inference" maxlength="1500">'+esc(n.inference||'')+'</textarea></label><label>Evidence: which short phrase supports your interpretation?<textarea name="evidence" maxlength="1000">'+esc(n.evidence||'')+'</textarea></label><button>Save reflection</button></form></section>'}
