const admin=()=>state?.role==='admin',student=()=>state?.role==='student';
function toast(message){by('toast').textContent=message;by('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>by('toast').classList.remove('show'),7000)}
async function run(fn,button){if(button)button.disabled=true;try{await fn()}catch(e){if(/LOCKDOWN/.test(e.message)){state=null;opened=null;app.innerHTML=`<main class="login"><div class="card"><h1>OneHome is paused</h1><p>${esc(e.message)}</p><p><a href="${esc(link('OneEducation'))}">Open ONE EDUCATE</a></p></div></main>`}else toast(e.message)}finally{if(button?.isConnected)button.disabled=false}}
async function baseCall(action,data={}){if(action==='status')data.student=mode==='student';if(demo){const {demoCall}=await import('./home-demo.mjs');return enrich(action,await demoCall(action,data,mode))}return enrich(action,await central('oh2_call',{p_slug:slug,p_action:action,p_data:data,p_code:code},!!identity()))}
