function serviceCards(){return `<div class="grid"><article class="card service"><img src="icon-reader.svg" alt=""><div><h2>OneReader</h2><p>Books, reading checks<br>and Star Points.</p><button data-service="reader">Open OneReader →</button></div></article><article class="card service maths"><img src="icon-maths.svg" alt=""><div><h2>OneMaths</h2><p>Homework, practice<br>and Power Points.</p><button data-service="maths">Open OneMaths →</button></div></article></div>`}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">Nothing to show yet.</td></tr>`}</tbody></table></div>`}
