function signin(message=''){state=null;app.innerHTML=`<main class="login"><section><img class="brand" src="onehome-logo-transparent.svg" alt="ONE HOME"><h1>A little learning.<br>A brighter day.</h1><p class="space">OneReader and OneMaths.<br>Your school’s shared learning home.</p><p class="space"><a href="?demo=1">Explore the demonstration</a></p></section><form class="card" id="signin"><div class="tabs"><button type="button" data-mode="staff" class="${mode==='student'?'secondary':''}">Staff</button><button type="button" data-mode="student" class="${mode==='student'?'':'secondary'}">Student</button></div><h2>Welcome back</h2><label>School address<input name="school" value="${esc(slug)}" pattern="[a-z0-9-]{3,48}" required placeholder="your-school"></label>${mode==='student'?'<div class="stack"><button type="button" id="microsoftLogin" class="secondary">Continue with Microsoft</button><button type="button" id="googleLogin" class="secondary">Continue with Google</button><label>School email<input id="studentEmail" type="email" autocomplete="email"></label><button type="button" id="emailLogin" class="quiet">Email me a sign-in code</button><label>Email verification code<input id="emailToken" autocomplete="one-time-code"></label><button type="button" id="verifyEmail">Verify email code</button></div><details class="space"><summary>Use an existing student code instead</summary><label>Private student code<input name="code" autocomplete="off"></label></details>':'<label>Email<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label>'}<button>Sign in</button><p class="error space" id="signinError">${esc(message)}</p><p class="privacy space">Use your existing school account. New staff are invited by your administrator after setup.</p></form></main>`;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;signin()});bindSignIn();by('signin').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const f=new FormData(e.target);if(f.get('school')!==slug){location.href='?school='+encodeURIComponent(f.get('school'));return}sessionStorage.setItem('onehome-mode',mode);if(mode==='student'){code=f.get('code').trim();if(!code)throw Error('Choose a school sign-in method above, or enter your existing student code.');state=await call('student',{login:true});sessionStorage.setItem('onehome-code',code);sessionStorage.setItem('onehome-school',slug)}else{await login(f.get('email'),f.get('password'));state=await call('staff')}view='home';if(student()){wallet=await call('wallet');advent=await call('advent_status')}render()}catch(err){by('signinError').textContent=/oh2_call/.test(err.message)?'The OneHome update SQL has not been installed. Ask your administrator to finish the update.':err.message}finally{if(e.submitter?.isConnected)e.submitter.disabled=false}}}
await finishOAuth().catch(e=>toast(e.message));
